import threading


def run_all(jobs):
    results = [None] * len(jobs)

    def run(index, job):
        results[index] = job()

    threads = [
        threading.Thread(target=run, args=(index, job))
        for index, job in enumerate(jobs)
    ]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    return results

