import queue
import threading


def process(items, handle, workers=3):
    jobs = queue.Queue()
    results = [None] * len(items)

    def worker():
        while True:
            job = jobs.get()
            if job is None:
                break
            index, item = job
            results[index] = handle(item)

    threads = [
        threading.Thread(target=worker)
        for _ in range(workers)
    ]
    for thread in threads:
        thread.start()
    for job in enumerate(items):
        jobs.put(job)
    for _ in threads:
        jobs.put(None)
    for thread in threads:
        thread.join()
    return results

